begin;
create extension if not exists pgtap with schema extensions;
grant execute on all functions in schema extensions to authenticated,anon,service_role;
set local search_path=public,extensions;
select no_plan();
select is(jetu_private.mentor_local_instant('2026-11-01','00:30','America/New_York'),'2026-11-01T04:30:00Z'::timestamptz,'normal DST-adjacent wall time converts exactly');
select throws_ok($$select jetu_private.mentor_local_instant('2026-11-01','01:30','America/New_York')$$,'23514',null,'ambiguous fall-back wall time rejected');
select throws_ok($$select jetu_private.mentor_local_instant('2027-03-14','02:30','America/New_York')$$,'23514',null,'nonexistent spring-forward wall time rejected');
select throws_ok($$select jetu_private.mentor_local_instant('2027-01-10','10:00','Invalid/Zone')$$,'23514',null,'invalid timezone rejected');
insert into auth.users(id,email) values('22200000-0000-4000-8000-000000000001','availability-x@example.invalid'),('22200000-0000-4000-8000-000000000002','availability-v@example.invalid');
insert into public.mentor_profiles(user_id,display_name,bio,expertise,languages,timezone,state,reviewed_by,reviewed_at,verified_summary) values('22200000-0000-4000-8000-000000000001','SYNTHETIC availability mentor','Isolated test fixture only',array['essays'],array['en'],'America/New_York','verified','22200000-0000-4000-8000-000000000002',now(),'SYNTHETIC fixture verification only');
create temp table availability_ids(k text primary key,v uuid);
create temp table availability_times(starts_at timestamptz,ends_at timestamptz);
grant select,insert,update on availability_ids,availability_times to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','22200000-0000-4000-8000-000000000001',true);
insert into availability_ids values('rule',(public.mentor_command(jsonb_build_object('op','weekly_slots','firstDate',current_date+7,'startTime','10:00','endTime','11:00','weeks',3,'key','22210000-0000-4000-8000-000000000001'))->>'id')::uuid);
select is((select count(*)::int from public.mentor_slots),3,'weekly rule materializes three real slots');
select is((select count(distinct starts_at at time zone 'America/New_York')::int from public.mentor_slots),3,'each weekly occurrence is distinct');
select lives_ok($$select public.mentor_command(jsonb_build_object('op','weekly_slots','firstDate',current_date+7,'startTime','10:00','endTime','11:00','weeks',3,'key','22210000-0000-4000-8000-000000000001'))$$,'weekly creation retry is idempotent');
select is((select count(*)::int from public.mentor_slots),3,'retry does not duplicate slots');
select throws_ok($$select public.mentor_command(jsonb_build_object('op','weekly_slots','firstDate',current_date+7,'startTime','10:30','endTime','11:30','weeks',3,'key','22210000-0000-4000-8000-000000000001'))$$,'23514',null,'same key cannot silently reschedule a recurring series');
select throws_ok($$select public.mentor_command(jsonb_build_object('op','weekly_slots','firstDate',current_date+7,'startTime','10:30','endTime','11:30','weeks',3,'key',gen_random_uuid()))$$,'23514',null,'overlapping weekly rule rolls back');
select is((select count(*)::int from public.mentor_availability_rules),1,'failed recurrence leaves no partial rule');
insert into availability_times select starts_at,ends_at from public.mentor_slots order by starts_at limit 1;
insert into availability_ids values('blackout',(public.mentor_command(jsonb_build_object('op','blackout','start',(select starts_at from availability_times),'end',(select ends_at from availability_times)))->>'id')::uuid);
select is((select count(*)::int from public.mentor_slots where cancelled_at is not null),1,'blackout cancels overlapping occurrence');
select throws_ok($$select public.mentor_command(jsonb_build_object('op','slot','start',(select starts_at+interval '10 minutes' from availability_times),'end',(select ends_at from availability_times),'timezone','America/New_York'))$$,'23514',null,'blackout also guards the existing explicit-slot command');
select lives_ok($$select public.mentor_command(jsonb_build_object('op','remove_blackout','id',(select v from availability_ids where k='blackout')))$$,'mentor can remove own blackout');
select is((select count(*)::int from public.mentor_slots where cancelled_at is not null),1,'removing blackout does not resurrect cancelled bookings');
select set_config('request.jwt.claim.sub','22200000-0000-4000-8000-000000000002',true);
select is((select count(*)::int from public.mentor_availability_rules),0,'other actor cannot list recurring availability rules');
select throws_ok($$select public.mentor_command(jsonb_build_object('op','cancel_rule','id',(select v from availability_ids where k='rule')))$$,'42501',null,'unverified unrelated actor cannot cancel another mentor series');
select set_config('request.jwt.claim.sub','22200000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.mentor_command(jsonb_build_object('op','cancel_rule','id',(select v from availability_ids where k='rule')))$$,'mentor can cancel all future recurring slots');
select is((select count(*)::int from public.mentor_slots where cancelled_at is null),0,'series cancellation leaves no active occurrence');
select throws_ok($$select public.mentor_retention_candidates()$$,'42501',null,'mentor cannot inspect retention metadata');
select throws_ok($$select public.mentor_retention_finish(gen_random_uuid())$$,'42501',null,'mentor cannot erase verification evidence');
reset role;
insert into public.mentor_evidence(id,mentor_id,claim,object_path,mime,byte_size,state,retain_until) values('22220000-0000-4000-8000-000000000001','22200000-0000-4000-8000-000000000001','SYNTHETIC expired evidence only','22200000-0000-4000-8000-000000000001/22220000-0000-4000-8000-000000000001','application/pdf',10,'reviewed',now()-interval '1 day');
insert into storage.objects(bucket_id,name) values('mentor-evidence','22200000-0000-4000-8000-000000000001/22220000-0000-4000-8000-000000000001');
set local role service_role;
select is(jsonb_array_length(public.mentor_retention_candidates()),1,'retention worker sees only expired evidence');
select throws_ok($$select public.mentor_retention_finish('22220000-0000-4000-8000-000000000001')$$,'23514',null,'metadata cannot claim purge before Storage removal');
reset role;
-- A distinct already-absent object tests completion without bypassing Storage's
-- protect_delete guard. Actual API removal is exercised in mentor-auth-test.mjs.
insert into public.mentor_evidence(id,mentor_id,claim,object_path,mime,byte_size,state,retain_until) values('22220000-0000-4000-8000-000000000002','22200000-0000-4000-8000-000000000001','SYNTHETIC already-absent evidence','22200000-0000-4000-8000-000000000001/22220000-0000-4000-8000-000000000002','application/pdf',10,'reviewed',now()-interval '1 day');
set local role service_role;
select lives_ok($$select public.mentor_retention_finish('22220000-0000-4000-8000-000000000002')$$,'worker redacts metadata after actual object removal');
select is(jsonb_array_length(public.mentor_retention_candidates()),1,'purged evidence is not reprocessed; blocked object remains pending');
reset role;
select is((select state from public.mentor_evidence where id='22220000-0000-4000-8000-000000000002'),'purged','purge state persists');
select * from finish();
rollback;
